import fs from 'node:fs';import {wikiPage,usableImages,getJson,getBytes} from './build-catalog.mjs';
const file='docs/research/venue-candidates-20261107.json',r=JSON.parse(fs.readFileSync(file,'utf8'));
const extra=[
 ['ha-noi','pho-bat-dan','Phở Gia Truyền · Bát Đàn','49 Bát Đàn, Hà Nội','https://guide.michelin.com/us/en/ha-noi/ha-noi_2974158/restaurant/pho-gia-truyen','Một bữa phở bò trong hành trình đi bộ khu phố cũ.','Phở Gia Truyền'],
 ['ho-chi-minh','ba-ghien','Cơm tấm Ba Ghiền','84 Đặng Văn Ngữ, Thành phố Hồ Chí Minh','https://guide.michelin.com/us/en/ho-chi-minh/ho-chi-minh_2978179/restaurant/com-tam-ba-ghien','Thử một bữa cơm tấm với sườn nướng, chọn phần ăn theo khẩu vị.','Ba Ghiền'],
 ['da-nang','ba-duong','Bánh xèo Bà Dưỡng','280/23 Hoàng Diệu, Đà Nẵng','https://guide.michelin.com/vn/en/da-nang-region/da-nang_2984390/restaurant/banh-xeo-ba-duong','Tìm vào con hẻm để thử bánh xèo cuốn rau và nước chấm của quán.','Bà Dưỡng'],
];
for(const [dest,slug,name,address,url,focus,q]of extra){const id=`venue-${dest}-${slug}`;if(r[id])continue;r[id]={id,dest,slug,name,address,url,focus,kind:'restaurant',checkedAt:'2026-11-07',approved:false,photos:[]};try{const p=new URLSearchParams({q,countrycodes:'vn',format:'jsonv2',limit:'6'}),res=await fetch('https://nominatim.openstreetmap.org/search?'+p,{headers:{'User-Agent':'WanderCatalog/0.1 (contact: https://github.com/dungv798/Wander)'},signal:AbortSignal.timeout(18000)});r[id].hits=await res.json();console.log(id,JSON.stringify(r[id].hits.map(h=>({lat:h.lat,lon:h.lon,name:h.display_name,id:h.osm_id}))));}catch(e){console.log(e.message);}fs.writeFileSync(file,JSON.stringify(r,null,2)+'\n');await new Promise(r=>setTimeout(r,1300));}
fs.mkdirSync('.logs/venue-photos-20261107',{recursive:true});
for(const[key,title]of [['ha-noi-metropole','Sofitel Legend Metropole Hanoi'],['ho-chi-minh-majestic','Hotel Majestic (Saigon)'],['hue-saigon-morin','Hotel Saigon Morin'],['da-lat-dalat-palace','Dalat Palace Hotel'],['ha-noi-giang','Cafe Giang']]){
const v=r['venue-'+key];if(v.photoCandidates)continue;v.photoCandidates=[];try{const p=await wikiPage(title),search=await getJson('https://commons.wikimedia.org/w/api.php',{action:'query',generator:'search',gsrsearch:`"${title}" filetype:bitmap`,gsrnamespace:'6',gsrlimit:'4'});const names=[...new Set([...(p?.lead?['File:'+p.lead]:[]),...Object.values(search.query?.pages??{}).map(p=>p.title)])],images=(await usableImages(names)).slice(0,3);for(const[i,img]of images.entries()){const file=`venue-${key}-${i+1}.jpg`;fs.writeFileSync('.logs/venue-photos-20261107/'+file,await getBytes(img.url));v.photoCandidates.push({...img,file});}console.log(key,v.photoCandidates.length);}catch(e){console.log(e.message);}fs.writeFileSync(file,JSON.stringify(r,null,2)+'\n');}
